OBJECTS = [
    ("logs/app.log", 45),
    ("backups/db.bak", 400),
    ("assets/logo.png", 10),
    ("exports/q1.csv", 120),
]

def target_class(age_days):
    if age_days >= 365:
        return "ARCHIVE"
    if age_days >= 90:
        return "COLDLINE"
    if age_days >= 30:
        return "NEARLINE"
    return "STANDARD"

for name, age in OBJECTS:
    target = target_class(age)
    if target == "STANDARD":
        print(f"{name} ({age}d): STANDARD (no change)")
    else:
        print(f"{name} ({age}d): STANDARD -> {target}")
